          gstr3b_filing_date = COALESCE(excluded.gstr3b_filing_date, returns_tracking_records.gstr3b_filing_date),
          gstr3b_liability = COALESCE(excluded.gstr3b_liability, returns_tracking_records.gstr3b_liability),
